const TeamsChatCanvasEmpty = () => {
  const { navigate, isPaused } = useContext(AppContext);
  const [isSearching, setIsSearching] = useState(true);
  const [bgImage, setBgImage] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    let mounted = true;

    // Load background image
    generateImage("A subtle, abstract background image representing 'connection' and 'data points merging'. Use a minimalist corporate style suitable for a Microsoft Teams empty state. Colors should be muted grays and soft whites with very subtle hints of deep red.")
      .then(url => { if (mounted && url) setBgImage(url); });

    // Simulate search & AI call
    const runSearch = async () => {
      try {
        if (isPaused) {
          setIsSearching(false);
          return;
        }

        // Simulate delay for realism
        await new Promise(r => setTimeout(r, 2000));

        // Fire AI call
        const maya = SEED_STUDENTS[0];
        await callAIWithFallback(
          "You are a matching engine. Given a first-year student's current courses and clubs, find the most similar upperclassmen based on their historical year-1 data. Return ONLY a JSON array of the top 5 mentor_ids with similarity scores.",
          `Find matches for ${maya.name} (Courses: ${maya.courses_in_progress.join(', ')}; Clubs: ${maya.clubs.join(', ')}) against the upperclassmen database.`
        );

        if (mounted) {
          setIsSearching(false);
          navigate('match_rationale_card');
        }
      } catch (err) {
        if (mounted) {
          setError("Unable to connect to Snowflake database.");
          setIsSearching(false);
        }
      }
    };

    runSearch();
    return () => { mounted = false; };
  }, [navigate, isPaused]);

  return (
    <TeamsLayout activeNav="chat">
      <ChatHeader title="Trailblazer Copilot" />
      <div className="chat-feed" style={bgImage ? { backgroundImage: `url(${bgImage})`, backgroundSize: 'cover', backgroundPosition: 'center' } : {}}>
        {SEED_CHAT.slice(0, 3).map(msg => 
          msg.sender === 'bot' ? <BotMessage key={msg.log_id} text={msg.message} /> : <UserMessage key={msg.log_id} text={msg.message} />
        )}

        {!isPaused && (
          <BotMessage text="Hi Maya, I'm analyzing your current courses and clubs to find upperclassmen who walked your exact path. I'll ping you when I find a strong match." />
        )}

        {isSearching && (
          <BotMessage>
            <LoadingDots />
          </BotMessage>
        )}

        {error && (
          <BotMessage>
            <div className="error-box">
              <p>{error}</p>
              <Button variant="secondary" onClick={() => setIsSearching(true)}>Retry</Button>
            </div>
          </BotMessage>
        )}

        {!isSearching && !error && isPaused && (
          <div className="empty-state-text">Waiting for new matches...</div>
        )}
      </div>
      <div className="chat-input-area">
        <div className="input-box disabled">
          <span>Type a message...</span>
          <lucide.Send size={16} />
        </div>
      </div>
    </TeamsLayout>
  );
};

