const IcebreakerCopilotModal = () => {
  const { navigate, draftsCache, setDraftsCache, showToast } = useContext(AppContext);
  const [isGenerating, setIsGenerating] = useState(true);
  const [drafts, setDrafts] = useState(draftsCache || []);
  const [selectedDraft, setSelectedDraft] = useState(0);
  const [editedText, setEditedText] = useState('');

  useEffect(() => {
    let mounted = true;
    if (draftsCache && draftsCache.length > 0) {
      setIsGenerating(false);
      setEditedText(draftsCache[0]);
      return;
    }

    const fetchDrafts = async () => {
      try {
        const res = await callAIWithVS(
          "You are a networking assistant helping an introverted first-year student draft a Teams message to an upperclassman. Generate 3 distinct, low-pressure conversation starters based on their shared background. Output ONLY a JSON array of 3 strings.",
          "Draft 3 icebreakers for Maya to send to Sam. Shared background: CS2500, Data Club. Mentor's current co-op: Microsoft. Tones: 1 Casual, 2 Direct, 3 Question-focused."
        );
        if (mounted) {
          try {
            // Clean markdown if present
            const cleanJson = res.text.replace(/```json/g, '').replace(/```/g, '').trim();
            const parsed = JSON.parse(cleanJson);
            if (Array.isArray(parsed) && parsed.length >= 3) {
              setDrafts(parsed);
              setDraftsCache(parsed);
              setEditedText(parsed[0]);
            } else {
              throw new Error("Invalid shape");
            }
          } catch (e) {
            throw new Error("Parse failed");
          }
          setIsGenerating(false);
        }
      } catch (err) {
        if (mounted) {
          const fallback = [
            "Hi Sam, Trailblazer suggested we connect. I'd love to hear about your experience at Microsoft!",
            "Hey Sam, I saw we both took CS2500. Do you have 10 mins to chat?",
            "Hi Sam, I'm trying to figure out my next steps and would value your advice."
          ];
          setDrafts(fallback);
          setDraftsCache(fallback);
          setEditedText(fallback[0]);
          setIsGenerating(false);
        }
      }
    };
    fetchDrafts();
    return () => { mounted = false; };
  }, [draftsCache, setDraftsCache]);

  const handleSelect = (idx) => {
    setSelectedDraft(idx);
    setEditedText(drafts[idx]);
  };

  const handleSend = () => {
    showToast('Message sent to Sam!');
    navigate('active_connections_tab');
  };

  return (
    <TeamsLayout activeNav="chat">
      <div className="modal-overlay">
        <motion.div 
          className="modal-container"
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.4, ease: [0.4, 0, 0.2, 1] }}
        >
          <div className="modal-header">
            <h3>Drafting message to Sam Taylor</h3>
            <p className="context-reminder">Referencing CS2500 and Data Club</p>
          </div>
          <div className="modal-body">
            {isGenerating ? (
              <div className="typewriter-skeleton">
                <div className="skel-bubble"><div className="shimmer-line"></div></div>
                <div className="skel-bubble"><div className="shimmer-line"></div></div>
                <div className="skel-bubble"><div className="shimmer-line"></div></div>
              </div>
            ) : (
              <div className="draft-list">
                {drafts.map((d, i) => (
                  <DraftBubble key={i} text={d} selected={selectedDraft === i} onClick={() => handleSelect(i)} />
                ))}
              </div>
            )}
            <textarea 
              className="edit-box" 
              value={editedText} 
              onChange={(e) => setEditedText(e.target.value)}
              disabled={isGenerating}
            />
          </div>
          <div className="modal-footer">
            <Button variant="text" onClick={() => navigate('match_rationale_card')}>Cancel</Button>
            <Button variant="primary" onClick={handleSend} disabled={isGenerating}>Send Introduction</Button>
          </div>
        </motion.div>
      </div>
    </TeamsLayout>
  );
};

