const PauseMatchingFlow = () => {
  const { navigate, isPaused, setIsPaused } = useContext(AppContext);
  const [isProcessing, setIsProcessing] = useState(true);
  const [intent, setIntent] = useState(null);

  useEffect(() => {
    let mounted = true;
    const checkIntent = async () => {
      try {
        const res = await callAIWithFallback(
          "You are an intent recognition router. Determine if the user wants to pause notifications, resume notifications, or ask a question. Return ONLY a JSON object with 'intent' and 'confidence_score'.",
          "User typed: 'pause matches'. Classify intent."
        );
        if (mounted) {
          try {
            const cleanJson = res.text.replace(/```json/g, '').replace(/```/g, '').trim();
            const parsed = JSON.parse(cleanJson);
            setIntent(parsed.intent);
            if (parsed.intent === 'pause') setIsPaused(true);
          } catch (e) {
            setIntent('pause');
            setIsPaused(true);
          }
          setIsProcessing(false);
        }
      } catch (err) {
        if (mounted) {
          setIntent('pause');
          setIsPaused(true);
          setIsProcessing(false);
        }
      }
    };
    checkIntent();
    return () => { mounted = false; };
  }, [setIsPaused]);

  return (
    <TeamsLayout activeNav="chat">
      <ChatHeader title="Trailblazer Copilot" />
      <div className="chat-feed">
        <UserMessage text="pause matches" />

        {isProcessing ? (
          <BotMessage><LoadingDots /></BotMessage>
        ) : (
          <motion.div initial={{ y: 10, opacity: 0 }} animate={{ y: 0, opacity: 1 }}>
            <BotMessage>
              <p>I've paused your Trailblazer matches for now. You won't receive any new introductions. Focus on those midterms!</p>
              <div className="adaptive-card mini">
                <Button variant="primary" onClick={() => { setIsPaused(false); navigate('teams_chat_canvas_empty'); }}>Resume in Spring</Button>
              </div>
            </BotMessage>
          </motion.div>
        )}
      </div>
      <div className="chat-input-area">
        <div className="input-box">
          <span>Type a message...</span>
          <lucide.Send size={16} />
        </div>
      </div>
    </TeamsLayout>
  );
};

